use super::*;
use crate::money::{money, Currency, Money};

/// The total for one month, ZERO if nothing is due — a month with no obligations is a real answer,
/// unlike a projection's absent total, which means "this does not know".
pub fn month_total(c: &ObligationCalendar, month: &str, currency: Currency) -> Money {
    c.by_month.iter().find(|m| m.month == month).map(|m| m.total).unwrap_or_else(|| money(0, currency))
}
